var t=`0207-pulpo-a-la-gallega`;var a=`world-0207`;var n=`ES`;var s=`southern-europe`;var l=4;var o=80;var r={en:`Pulpo a la Gallega`,ua:`Восьминіг по-галісійськи`};var d={en:`A traditional Spain dish made with octopus, bay leaf, potato, flaky sea salt. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Іспанія. Основні інгредієнти: восьминіг, лавровий лист, картопля, морська сіль пластівцями. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Simmer the cleaned octopus in water with bay leaves until a skewer slides easily into a thick tentacle, typically 45–60 minutes; rest in its broth.`,ua:`Варіть очищеного восьминога у воді з лавровим листом до м’якості, щоб шпажка легко входила в товсте щупальце (приблизно 45–60 хвилин); дайте постояти у відварі.`,t:[`boiling`],m:55,i:[[`octopus`,900,`g`],[`water`,1500,`ml`],[`bay-leaf`,2,`leaf`]]},{en:`Cook the listed ingredients in simmering water for about 18 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 18 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:18,i:[[`potato`,550,`g`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:4,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`extra-virgin-olive-oil`,60,`ml`],[`smoked-paprika`,5,`g`],[`flaky-sea-salt`,6,`g`]]}];var g={slug:t,id:a,country:`ES`,region:s,servings:4,minutes:80,title:r,text:d,steps:u};export{n as country,g as default,a as id,o as minutes,s as region,l as servings,t as slug,u as steps,d as text,r as title};